insert into public.products (slug, name, category, short, description, images, sizes, flavors, decorations, allow_message, lead_days, prep_hours, badge, bestseller, details, tint, sort, active) values
  ('build-your-box', 'Build Your Own Box', 'cookies', 'Mix and match any flavours in a pack of 2, 4 or 6.', 'Can’t choose just one? Pick your pack size, then fill it with any mix of our cookie flavours. Boxed and ribboned, ready to gift.', '["packaging","cookies"]'::jsonb, '[{"id":"pack2","label":"Pack of 2","servings":"2 cookies","price":10},{"id":"pack4","label":"Pack of 4","servings":"4 cookies","price":19},{"id":"pack6","label":"Pack of 6","servings":"6 cookies","price":27}]'::jsonb, '[{"label":"Classic Chocolate Chip","price":0},{"label":"Double Chocolate Fudge","price":0},{"label":"Biscoff Crumble","price":0},{"label":"Red Velvet Cheesecake","price":0},{"label":"S’mores","price":0},{"label":"Birthday Funfetti","price":0}]'::jsonb, '[]'::jsonb, false, 1, 3, 'Mix & match', true, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Size","value":"Each cookie is about 5 oz — thick, crisp at the edges and soft in the middle."},{"label":"Storage","value":"Keep in the box at room temperature for up to 3 days. Warm for 5 minutes at 350°F for that just-baked feel."}]'::jsonb, '#EFEEE6', 0, true),
  ('classic-chocolate-chip', 'Classic Chocolate Chip', 'cookies', 'Brown butter dough, dark chocolate chunks and flaky sea salt.', 'The one that started it all. A thick New York–style cookie made with nutty brown butter and loaded with puddles of dark and milk chocolate, finished with flaky sea salt.', '["cookies","packaging"]'::jsonb, '[{"id":"pack2","label":"Pack of 2","servings":"2 cookies","price":10},{"id":"pack4","label":"Pack of 4","servings":"4 cookies","price":19},{"id":"pack6","label":"Pack of 6","servings":"6 cookies","price":27}]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, 1, 3, 'Bestseller', true, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Size","value":"Each cookie is about 5 oz — thick, crisp at the edges and soft in the middle."},{"label":"Storage","value":"Keep in the box at room temperature for up to 3 days. Warm for 5 minutes at 350°F for that just-baked feel."}]'::jsonb, '#F6E7E3', 1, true),
  ('double-chocolate-fudge', 'Double Chocolate Fudge', 'cookies', 'Dark cocoa dough with a molten fudge centre.', 'For serious chocolate lovers: a deep cocoa cookie studded with white and dark chocolate, hiding a soft, molten fudge centre.', '["cookies","packaging"]'::jsonb, '[{"id":"pack2","label":"Pack of 2","servings":"2 cookies","price":10},{"id":"pack4","label":"Pack of 4","servings":"4 cookies","price":19},{"id":"pack6","label":"Pack of 6","servings":"6 cookies","price":27}]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, 1, 3, null, true, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Size","value":"Each cookie is about 5 oz — thick, crisp at the edges and soft in the middle."},{"label":"Storage","value":"Keep in the box at room temperature for up to 3 days. Warm for 5 minutes at 350°F for that just-baked feel."}]'::jsonb, '#EFEEE6', 2, true),
  ('biscoff-crumble', 'Biscoff Crumble', 'cookies', 'Cookie-butter centre, white chocolate and Biscoff crumb.', 'A brown sugar cookie stuffed with a gooey Biscoff cookie-butter centre, topped with white chocolate and crushed Lotus biscuits.', '["cookies","packaging"]'::jsonb, '[{"id":"pack2","label":"Pack of 2","servings":"2 cookies","price":10},{"id":"pack4","label":"Pack of 4","servings":"4 cookies","price":19},{"id":"pack6","label":"Pack of 6","servings":"6 cookies","price":27}]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, 1, 3, 'Fan favourite', true, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Size","value":"Each cookie is about 5 oz — thick, crisp at the edges and soft in the middle."},{"label":"Storage","value":"Keep in the box at room temperature for up to 3 days. Warm for 5 minutes at 350°F for that just-baked feel."}]'::jsonb, '#F6E7E3', 3, true),
  ('red-velvet-cheesecake', 'Red Velvet Cheesecake', 'cookies', 'Cocoa red velvet with a cream cheese heart.', 'Soft red velvet dough with white chocolate chips, wrapped around a tangy, creamy cheesecake centre.', '["cookies","packaging"]'::jsonb, '[{"id":"pack2","label":"Pack of 2","servings":"2 cookies","price":10},{"id":"pack4","label":"Pack of 4","servings":"4 cookies","price":19},{"id":"pack6","label":"Pack of 6","servings":"6 cookies","price":27}]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, 1, 3, null, true, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Size","value":"Each cookie is about 5 oz — thick, crisp at the edges and soft in the middle."},{"label":"Storage","value":"Keep in the box at room temperature for up to 3 days. Warm for 5 minutes at 350°F for that just-baked feel."}]'::jsonb, '#EFEEE6', 4, true),
  ('smores', 'S’mores', 'cookies', 'Graham dough, milk chocolate and toasted marshmallow.', 'Campfire in a cookie: graham cracker dough, milk chocolate chunks and a gooey marshmallow centre, toasted on top.', '["cookies","packaging"]'::jsonb, '[{"id":"pack2","label":"Pack of 2","servings":"2 cookies","price":10},{"id":"pack4","label":"Pack of 4","servings":"4 cookies","price":19},{"id":"pack6","label":"Pack of 6","servings":"6 cookies","price":27}]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, 1, 3, null, false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Size","value":"Each cookie is about 5 oz — thick, crisp at the edges and soft in the middle."},{"label":"Storage","value":"Keep in the box at room temperature for up to 3 days. Warm for 5 minutes at 350°F for that just-baked feel."}]'::jsonb, '#F6E7E3', 5, true),
  ('birthday-funfetti', 'Birthday Funfetti', 'cookies', 'Vanilla dough, rainbow sprinkles and white chocolate.', 'Every day is a celebration: buttery vanilla dough packed with rainbow sprinkles and creamy white chocolate.', '["cookies","packaging"]'::jsonb, '[{"id":"pack2","label":"Pack of 2","servings":"2 cookies","price":10},{"id":"pack4","label":"Pack of 4","servings":"4 cookies","price":19},{"id":"pack6","label":"Pack of 6","servings":"6 cookies","price":27}]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, 1, 3, null, false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Size","value":"Each cookie is about 5 oz — thick, crisp at the edges and soft in the middle."},{"label":"Storage","value":"Keep in the box at room temperature for up to 3 days. Warm for 5 minutes at 350°F for that just-baked feel."}]'::jsonb, '#EFEEE6', 6, true),
  ('strawberry-dream-cake', 'Strawberry Dream Cake', 'cakes', 'Vanilla sponge, fresh strawberries and whipped mascarpone cream.', 'Our most-requested cake. Three layers of light vanilla bean sponge, filled with macerated summer strawberries and a cloud of whipped mascarpone cream, finished with a soft-textured buttercream and a crown of fresh berries.', '["strawberry","sliced","celebration"]'::jsonb, '[{"id":"6in","label":"6\" round","servings":"8–10 servings","price":68},{"id":"8in","label":"8\" round","servings":"14–18 servings","price":94},{"id":"10in","label":"10\" round","servings":"24–30 servings","price":126}]'::jsonb, '[{"label":"Vanilla bean sponge","price":0},{"label":"Lemon sponge","price":0},{"label":"Gluten-free vanilla","price":8}]'::jsonb, '[{"id":"classic","label":"Classic Sweet Daisy finish","price":0},{"id":"fresh-flowers","label":"Fresh seasonal flowers","price":18},{"id":"gold-leaf","label":"Edible gold leaf accents","price":14},{"id":"berries","label":"Fresh berry crown","price":12}]'::jsonb, true, 2, 24, 'Bestseller', false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#F6E7E3', 100, false),
  ('vanilla-daisy-cake', 'Vanilla Daisy Cake', 'cakes', 'Madagascar vanilla, silky Swiss meringue buttercream, piped daisies.', 'The cake our studio is named after. A buttery Madagascar vanilla sponge layered with silky Swiss meringue buttercream and a whisper of white chocolate ganache, hand-piped with delicate daisies.', '["vanilla","floral","hero"]'::jsonb, '[{"id":"6in","label":"6\" round","servings":"8–10 servings","price":64},{"id":"8in","label":"8\" round","servings":"14–18 servings","price":90},{"id":"10in","label":"10\" round","servings":"24–30 servings","price":122}]'::jsonb, '[{"label":"Vanilla bean sponge","price":0},{"label":"Almond sponge","price":0},{"label":"Gluten-free vanilla","price":8}]'::jsonb, '[{"id":"classic","label":"Classic Sweet Daisy finish","price":0},{"id":"fresh-flowers","label":"Fresh seasonal flowers","price":18},{"id":"gold-leaf","label":"Edible gold leaf accents","price":14},{"id":"berries","label":"Fresh berry crown","price":12}]'::jsonb, true, 2, 24, 'Signature', false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#EFEEE6', 101, false),
  ('chocolate-velvet-cake', 'Chocolate Velvet Cake', 'cakes', 'Dark cocoa sponge, salted caramel and a glossy ganache drip.', 'For the chocolate devoted. Moist dark cocoa layers with a ribbon of house-made salted caramel, whipped milk chocolate ganache and a glossy 64% dark chocolate drip.', '["chocolate","chocolateAlt","sliced"]'::jsonb, '[{"id":"6in","label":"6\" round","servings":"8–10 servings","price":72},{"id":"8in","label":"8\" round","servings":"14–18 servings","price":98},{"id":"10in","label":"10\" round","servings":"24–30 servings","price":130}]'::jsonb, '[{"label":"Dark chocolate sponge","price":0},{"label":"Chocolate & hazelnut","price":0},{"label":"Gluten-free chocolate","price":8}]'::jsonb, '[{"id":"classic","label":"Classic Sweet Daisy finish","price":0},{"id":"fresh-flowers","label":"Fresh seasonal flowers","price":18},{"id":"gold-leaf","label":"Edible gold leaf accents","price":14},{"id":"berries","label":"Fresh berry crown","price":12}]'::jsonb, true, 2, 24, null, false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#F6E7E3', 102, false),
  ('lemon-cream-cake', 'Lemon Cream Cake', 'cakes', 'Lemon chiffon, tangy curd and soft vanilla cream.', 'Bright and elegant. Feather-light lemon chiffon layered with tangy house-made lemon curd and vanilla chantilly, finished with candied lemon and tiny edible flowers.', '["lemon","floral","vanilla"]'::jsonb, '[{"id":"6in","label":"6\" round","servings":"8–10 servings","price":66},{"id":"8in","label":"8\" round","servings":"14–18 servings","price":92},{"id":"10in","label":"10\" round","servings":"24–30 servings","price":124}]'::jsonb, '[{"label":"Lemon chiffon","price":0},{"label":"Lemon & elderflower","price":0},{"label":"Gluten-free lemon","price":8}]'::jsonb, '[{"id":"classic","label":"Classic Sweet Daisy finish","price":0},{"id":"fresh-flowers","label":"Fresh seasonal flowers","price":18},{"id":"gold-leaf","label":"Edible gold leaf accents","price":14},{"id":"berries","label":"Fresh berry crown","price":12}]'::jsonb, true, 2, 24, null, false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#EFEEE6', 103, false),
  ('pistachio-rose-cake', 'Pistachio Rose Cake', 'cakes', 'Pistachio sponge, raspberry and a delicate rose buttercream.', 'Our most romantic cake. Toasted pistachio sponge layered with raspberry compote and a softly perfumed rose buttercream, scattered with crushed pistachio and dried petals.', '["pistachio","floral","wedding"]'::jsonb, '[{"id":"6in","label":"6\" round","servings":"8–10 servings","price":74},{"id":"8in","label":"8\" round","servings":"14–18 servings","price":100},{"id":"10in","label":"10\" round","servings":"24–30 servings","price":132}]'::jsonb, '[{"label":"Pistachio sponge","price":0},{"label":"Vanilla sponge","price":0}]'::jsonb, '[{"id":"classic","label":"Classic Sweet Daisy finish","price":0},{"id":"fresh-flowers","label":"Fresh seasonal flowers","price":18},{"id":"gold-leaf","label":"Edible gold leaf accents","price":14},{"id":"berries","label":"Fresh berry crown","price":12}]'::jsonb, true, 3, 30, 'New', false, '[{"label":"Allergens","value":"Contains pistachio, wheat, eggs, dairy."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#F6E7E3', 104, false),
  ('carrot-walnut-cake', 'Carrot & Walnut Cake', 'cakes', 'Spiced carrot sponge, toasted walnuts, cream cheese frosting.', 'A classic made beautifully. Warmly spiced carrot sponge with toasted walnuts and golden raisins, layered with a tangy cream cheese frosting and finished with a semi-naked texture.', '["carrot","sliced","studio"]'::jsonb, '[{"id":"6in","label":"6\" round","servings":"8–10 servings","price":62},{"id":"8in","label":"8\" round","servings":"14–18 servings","price":88},{"id":"10in","label":"10\" round","servings":"24–30 servings","price":120}]'::jsonb, '[{"label":"Classic with walnuts","price":0},{"label":"Nut-free","price":0}]'::jsonb, '[{"id":"classic","label":"Classic Sweet Daisy finish","price":0},{"id":"fresh-flowers","label":"Fresh seasonal flowers","price":18},{"id":"gold-leaf","label":"Edible gold leaf accents","price":14},{"id":"berries","label":"Fresh berry crown","price":12}]'::jsonb, true, 2, 24, null, false, '[{"label":"Allergens","value":"Contains walnuts, wheat, eggs, dairy."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#EFEEE6', 105, false),
  ('mini-celebration-cake', 'Mini Celebration Cake', 'mini-cakes', 'A 4" cake for two to four — every bit as special.', 'All the ceremony of a full cake, sized for small moments. Choose your flavour and we will finish it with our signature textured buttercream and a hand-lettered message.', '["mini","birthday","floral"]'::jsonb, '[{"id":"4in","label":"4\" mini","servings":"2–4 servings","price":38},{"id":"5in","label":"5\" petite","servings":"4–6 servings","price":46}]'::jsonb, '[{"label":"Vanilla & strawberry","price":0},{"label":"Chocolate velvet","price":0},{"label":"Lemon cream","price":0},{"label":"Pistachio rose","price":0}]'::jsonb, '[{"id":"classic","label":"Classic Sweet Daisy finish","price":0},{"id":"fresh-flowers","label":"Fresh seasonal flowers","price":18},{"id":"gold-leaf","label":"Edible gold leaf accents","price":14}]'::jsonb, true, 1, 6, 'Bestseller', false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#F6E7E3', 106, false),
  ('bento-heart-cake', 'Bento Heart Cake', 'mini-cakes', 'A heart-shaped mini cake in a keepsake gift box.', 'A sweet little love letter. A heart-shaped vanilla or chocolate mini cake, piped in vintage style and presented in our keepsake box — perfect for anniversaries and just-because moments.', '["birthday","mini"]'::jsonb, '[{"id":"one","label":"Heart mini","servings":"1–2 servings","price":32}]'::jsonb, '[{"label":"Vanilla & raspberry","price":0},{"label":"Chocolate velvet","price":0}]'::jsonb, '[]'::jsonb, true, 1, 4, null, false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#EFEEE6', 107, false),
  ('signature-cupcake-box', 'Signature Cupcake Box', 'cupcakes', 'An assortment of our signature cupcakes, beautifully boxed.', 'Our signature flavours in one elegant box: vanilla daisy, chocolate velvet, strawberry dream and lemon cream — each one piped by hand and topped with a little detail.', '["cupcakes","cupcakesAlt","packaging"]'::jsonb, '[{"id":"box6","label":"Box of 6","servings":"6 cupcakes","price":36},{"id":"box12","label":"Box of 12","servings":"12 cupcakes","price":68},{"id":"box24","label":"Box of 24","servings":"24 cupcakes","price":128}]'::jsonb, '[{"label":"Signature assortment","price":0},{"label":"All vanilla daisy","price":0},{"label":"All chocolate velvet","price":0}]'::jsonb, '[]'::jsonb, true, 1, 5, null, false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#F6E7E3', 108, false),
  ('vanilla-bean-cupcakes', 'Vanilla Bean Cupcakes', 'cupcakes', 'Classic vanilla with a swirl of silky buttercream.', 'Simple, perfect and loved by everyone. Madagascar vanilla cupcakes with a generous swirl of vanilla Swiss meringue buttercream and a sugar daisy.', '["cupcakesAlt","cupcakes"]'::jsonb, '[{"id":"box6","label":"Box of 6","servings":"6 cupcakes","price":32},{"id":"box12","label":"Box of 12","servings":"12 cupcakes","price":60}]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, 1, 4, null, false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#EFEEE6', 109, false),
  ('macaron-gift-box', 'Macaron Gift Box', 'treats', 'Delicate French macarons in seasonal flavours.', 'Crisp shells, chewy centres and silky fillings. A curated box of French macarons in our current flavours — salted caramel, pistachio, raspberry, lemon, vanilla and chocolate.', '["macarons","dessertBox"]'::jsonb, '[{"id":"box12","label":"Box of 12","servings":"12 macarons","price":34},{"id":"box24","label":"Box of 24","servings":"24 macarons","price":64}]'::jsonb, '[]'::jsonb, '[]'::jsonb, true, 1, 24, null, false, '[{"label":"Allergens","value":"Contains almonds, eggs, dairy. Naturally gluten-free."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#F6E7E3', 110, false),
  ('sweet-daisy-dessert-box', 'Sweet Daisy Dessert Box', 'treats', 'Mini tarts, macarons, cookies and cake bites to share.', 'A grazing box for gatherings: mini fruit tarts, macarons, brown butter cookies and bite-sized cake squares, arranged by hand and wrapped with ribbon.', '["dessertBox","tart","cookies"]'::jsonb, '[{"id":"small","label":"Petite box","servings":"Serves 4–6","price":48},{"id":"large","label":"Grand box","servings":"Serves 10–12","price":92}]'::jsonb, '[]'::jsonb, '[]'::jsonb, true, 2, 8, 'Gift favourite', false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#EFEEE6', 111, false),
  ('brown-butter-cookies', 'Brown Butter Cookies', 'treats', 'Chewy brown butter cookies with dark chocolate and sea salt.', 'Thick, chewy cookies made with nutty brown butter, chunks of dark chocolate and a sprinkle of flaky sea salt. Baked fresh every morning.', '["cookies","packaging"]'::jsonb, '[{"id":"box6","label":"Box of 6","servings":"6 cookies","price":18},{"id":"box12","label":"Box of 12","servings":"12 cookies","price":34}]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, 0, 2, null, false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#F6E7E3', 112, false),
  ('berry-tartlets', 'Berry Tartlets', 'treats', 'Butter pastry, vanilla crème pâtissière and fresh berries.', 'Crisp, buttery pastry shells filled with vanilla crème pâtissière and topped with glazed fresh berries. A little bit of Paris in every bite.', '["tart","seasonal"]'::jsonb, '[{"id":"box4","label":"Box of 4","servings":"4 tartlets","price":26},{"id":"box8","label":"Box of 8","servings":"8 tartlets","price":48}]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, 1, 5, null, false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#EFEEE6', 113, false),
  ('autumn-spice-cake', 'Autumn Spice Cake', 'seasonal', 'Brown sugar spice, poached pear and maple cream.', 'Available for a limited time. Brown sugar and cinnamon sponge layered with vanilla-poached pears and a silky maple cream cheese frosting, finished with caramelised pecans.', '["seasonal","carrot","sliced"]'::jsonb, '[{"id":"6in","label":"6\" round","servings":"8–10 servings","price":70},{"id":"8in","label":"8\" round","servings":"14–18 servings","price":96},{"id":"10in","label":"10\" round","servings":"24–30 servings","price":128}]'::jsonb, '[{"label":"Spice & pear","price":0},{"label":"Spice & apple","price":0}]'::jsonb, '[{"id":"classic","label":"Classic Sweet Daisy finish","price":0},{"id":"fresh-flowers","label":"Fresh seasonal flowers","price":18},{"id":"gold-leaf","label":"Edible gold leaf accents","price":14},{"id":"berries","label":"Fresh berry crown","price":12}]'::jsonb, true, 2, 24, 'Limited', false, '[{"label":"Allergens","value":"Contains pecans, wheat, eggs, dairy."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#F6E7E3', 114, false),
  ('seasonal-treat-box', 'Seasonal Treat Box', 'seasonal', 'A rotating selection of our limited-edition bakes.', 'Our pastry team’s favourite seasonal creations in one box — expect spiced cookies, fruit tartlets, mini cakes and something new each month.', '["dessertBox","seasonal","macarons"]'::jsonb, '[{"id":"box","label":"Seasonal box","servings":"Serves 4–6","price":54}]'::jsonb, '[]'::jsonb, '[]'::jsonb, true, 2, 10, 'Limited', false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#EFEEE6', 115, false)
